from b200probe import cuda_kernel, harness_time, sass
import torch, time
src = r'''
extern "C" __global__ void ffma_k(float* out, int iters, float a, float b){
    float x0=threadIdx.x*1e-6f, x1=x0+1, x2=x0+2, x3=x0+3, x4=x0+4, x5=x0+5, x6=x0+6, x7=x0+7;
    for(int i=0;i<iters;i++){
        x0=fmaf(x0,a,b); x1=fmaf(x1,a,b); x2=fmaf(x2,a,b); x3=fmaf(x3,a,b);
        x4=fmaf(x4,a,b); x5=fmaf(x5,a,b); x6=fmaf(x6,a,b); x7=fmaf(x7,a,b);
    }
    if (x0+x1+x2+x3+x4+x5+x6+x7 == 12345.f) out[0]=x0;
}
extern "C" __global__ void ffma2_k(float* out, int iters, float a, float b){
    float x0=threadIdx.x*1e-6f, x1=x0+1, x2=x0+2, x3=x0+3, x4=x0+4, x5=x0+5, x6=x0+6, x7=x0+7;
    for(int i=0;i<iters;i++){
        asm volatile("{\n .reg .b64 ra, rb, r0, r1, r2, r3;\n"
          "mov.b64 ra, {%8,%8}; mov.b64 rb, {%9,%9};\n"
          "mov.b64 r0, {%0,%1}; mov.b64 r1, {%2,%3}; mov.b64 r2, {%4,%5}; mov.b64 r3, {%6,%7};\n"
          "fma.rn.f32x2 r0, r0, ra, rb; fma.rn.f32x2 r1, r1, ra, rb; fma.rn.f32x2 r2, r2, ra, rb; fma.rn.f32x2 r3, r3, ra, rb;\n"
          "mov.b64 {%0,%1}, r0; mov.b64 {%2,%3}, r1; mov.b64 {%4,%5}, r2; mov.b64 {%6,%7}, r3;\n}"
          : "+f"(x0),"+f"(x1),"+f"(x2),"+f"(x3),"+f"(x4),"+f"(x5),"+f"(x6),"+f"(x7) : "f"(a), "f"(b));
    }
    if (x0+x1+x2+x3+x4+x5+x6+x7 == 12345.f) out[0]=x0;
}
'''
k1 = cuda_kernel(src, "ffma_k"); k2 = cuda_kernel(src, "ffma2_k")
out = torch.zeros(4, device='cuda')
iters = 20000
for name,k in [("ffma",k1),("ffma2",k2)]:
    for blocks in [148*4, 148*8]:
        k((blocks,1,1),(256,1,1), out, iters, 0.999, 0.001); torch.cuda.synchronize()
        t0=time.perf_counter()
        for _ in range(5): k((blocks,1,1),(256,1,1), out, iters, 0.999, 0.001)
        torch.cuda.synchronize(); dt=(time.perf_counter()-t0)/5
        flops = 2.0*8*iters*256*blocks
        print(f"{name} blocks={blocks}: {dt*1e3:.2f} ms  {flops/dt/1e12:.1f} TFLOP/s")
