// ConvNeXtV2 block with GRN: one cooperative launch, three phases, fp32 SIMT.
//  P1: depthwise 7x7 conv (+bias) -> xn [M][C] (channels-last), per-token LN stats; zero GRN sums; transpose weights
//  P2: hidden = gelu(LN(xn) @ W1^T + b1) -> [M][4C]; sumsq[b][k] += hidden^2 (per image)
//  P3: out = x + (hidden * (1 + gw*nf) + gb) @ W2^T + b2, written NCHW
#include <cuda_runtime.h>
#include <cooperative_groups.h>
#include <stdint.h>
namespace cg = cooperative_groups;

#define NT 256
#define BK 32
#define MAXIMG 5
#define GEMM_SMEM_FLOATS (128 * 129)
#define SMEM_BYTES (GEMM_SMEM_FLOATS * 4 + MAXIMG * 128 * 4 + 64)

struct Params {
  const float* x; const float* dww; const float* dwb; const float* lnw; const float* lnb;
  const float* w1; const float* b1; const float* gw; const float* gb; const float* w2; const float* b2;
  float* out;
  float* xn; float* stats; float* hidden; float* sumsq; float* w1t; float* w2t;
  int B, C, H, W, HW, M, C4;
  float eps, ln_eps;
  int p1_mode, p1_tiles, p1_hq, p1_wq;
  int cfg2, cfg3;
};

__device__ __forceinline__ float gelu_f(float v) { return 0.5f * v * (1.f + erff(v * 0.70710678118654752f)); }

__device__ __forceinline__ float warp_sum(float v) {
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffffu, v, o);
  return v;
}

// ---------------------------------------------------------------- phase 1 helpers
__device__ void transpose_mat(const float* __restrict__ src, int R, int Cc, float* __restrict__ dst, float* tile) {
  // src [R][Cc] -> dst [Cc][R]
  const int rt = (R + 31) / 32, ct = (Cc + 31) / 32;
  const int tid = threadIdx.x, j = tid & 31, i0 = tid >> 5;
  for (int t = blockIdx.x; t < rt * ct; t += gridDim.x) {
    const int tr = t / ct, tc = t % ct;
#pragma unroll
    for (int s = 0; s < 4; s++) {
      const int i = i0 + 8 * s, r = tr * 32 + i, c = tc * 32 + j;
      tile[i * 33 + j] = (r < R && c < Cc) ? src[(size_t)r * Cc + c] : 0.f;
    }
    __syncthreads();
#pragma unroll
    for (int s = 0; s < 4; s++) {
      const int i = i0 + 8 * s, c = tc * 32 + i, r = tr * 32 + j;
      if (r < R && c < Cc) dst[(size_t)c * R + r] = tile[j * 33 + i];
    }
    __syncthreads();
  }
}

__device__ void phase1(const Params& p, float* smem) {
  const int tid = threadIdx.x, warp = tid >> 5, lane = tid & 31;
  const int C = p.C, H = p.H, W = p.W, HW = p.HW, M = p.M;
  // zero GRN sums
  for (int i = blockIdx.x * NT + tid; i < p.B * p.C4; i += gridDim.x * NT) p.sumsq[i] = 0.f;
  // weight transposes
  transpose_mat(p.w1, p.C4, C, p.w1t, smem);
  transpose_mat(p.w2, C, p.C4, p.w2t, smem);

  float* Xs = smem;                       // [32][129]
  float* st_s = smem + 32 * 129;          // [8][128][2]
  int* tok_s = (int*)(st_s + 8 * 128 * 2);  // [128]

  for (int tile = blockIdx.x; tile < p.p1_tiles; tile += gridDim.x) {
    int tok[4], bb[4], hh[4], ww[4]; bool val[4];
    int nb = 0, h0 = 0, w = 0;
    if (p.p1_mode == 1) {
      const int per = p.p1_hq * p.p1_wq;
      nb = tile / per; const int rem = tile - nb * per;
      const int hq = rem / p.p1_wq, wqi = rem - hq * p.p1_wq;
      w = wqi * 32 + lane; h0 = hq * 4;
#pragma unroll
      for (int r = 0; r < 4; r++) {
        const int h = h0 + r;
        val[r] = (w < W) && (h < H);
        tok[r] = nb * HW + h * W + w; bb[r] = nb; hh[r] = h; ww[r] = w;
      }
    } else {
#pragma unroll
      for (int r = 0; r < 4; r++) {
        const int t = tile * 128 + r * 32 + lane;
        val[r] = t < M;
        const int tt = val[r] ? t : 0;
        const int b = tt / HW; const int rem = tt - b * HW; const int h = rem / W;
        tok[r] = t; bb[r] = b; hh[r] = h; ww[r] = rem - h * W;
      }
    }
    if (tid < 128) {
      const int r = tid >> 5;
      tok_s[tid] = val[r] ? tok[r] : -1;
    }
    float s1[4] = {0.f, 0.f, 0.f, 0.f}, s2[4] = {0.f, 0.f, 0.f, 0.f};

    for (int cc = 0; cc < C / 32; cc++) {
#pragma unroll 1
      for (int cl = 0; cl < 4; cl++) {
        const int c = cc * 32 + warp * 4 + cl;
        const float* wk = p.dww + (size_t)c * 49;
        float acc[4] = {0.f, 0.f, 0.f, 0.f};
        if (p.p1_mode == 1) {
          const float* xc = p.x + ((size_t)nb * C + c) * HW;
#pragma unroll 1
          for (int j = 0; j < 7; j++) {
            const int ww2 = w + j - 3;
            const bool okw = (ww2 >= 0) && (ww2 < W);
            float wt[7], v[10];
#pragma unroll
            for (int i = 0; i < 7; i++) wt[i] = __ldg(wk + i * 7 + j);
#pragma unroll
            for (int i = 0; i < 10; i++) {
              const int hh2 = h0 - 3 + i;
              v[i] = (okw && hh2 >= 0 && hh2 < H) ? __ldg(xc + hh2 * W + ww2) : 0.f;
            }
#pragma unroll
            for (int r = 0; r < 4; r++)
#pragma unroll
              for (int i = 0; i < 7; i++) acc[r] = fmaf(v[r + i], wt[i], acc[r]);
          }
        } else {
#pragma unroll 1
          for (int i = 0; i < 7; i++) {
#pragma unroll 1
            for (int j = 0; j < 7; j++) {
              const float wt = __ldg(wk + i * 7 + j);
#pragma unroll
              for (int r = 0; r < 4; r++) {
                const int hh2 = hh[r] - 3 + i, ww2 = ww[r] - 3 + j;
                if (val[r] && hh2 >= 0 && hh2 < H && ww2 >= 0 && ww2 < W)
                  acc[r] = fmaf(__ldg(p.x + ((size_t)bb[r] * C + c) * HW + hh2 * W + ww2), wt, acc[r]);
              }
            }
          }
        }
        const float bias = __ldg(p.dwb + c);
#pragma unroll
        for (int r = 0; r < 4; r++) {
          const float v = val[r] ? acc[r] + bias : 0.f;
          Xs[(warp * 4 + cl) * 129 + r * 32 + lane] = v;
          s1[r] += v; s2[r] = fmaf(v, v, s2[r]);
        }
      }
      __syncthreads();
      {
        const int slot = tid >> 1, half = tid & 1;
        const int t = tok_s[slot];
        if (t >= 0) {
          float* base = p.xn + (size_t)t * C + cc * 32 + half * 16;
#pragma unroll
          for (int j = 0; j < 4; j++) {
            const int c0 = half * 16 + 4 * j;
            float4 v;
            v.x = Xs[(c0 + 0) * 129 + slot]; v.y = Xs[(c0 + 1) * 129 + slot];
            v.z = Xs[(c0 + 2) * 129 + slot]; v.w = Xs[(c0 + 3) * 129 + slot];
            *reinterpret_cast<float4*>(base + 4 * j) = v;
          }
        }
      }
      __syncthreads();
    }
#pragma unroll
    for (int r = 0; r < 4; r++) {
      st_s[(warp * 128 + r * 32 + lane) * 2 + 0] = s1[r];
      st_s[(warp * 128 + r * 32 + lane) * 2 + 1] = s2[r];
    }
    __syncthreads();
    if (tid < 128) {
      const int t = tok_s[tid];
      if (t >= 0) {
        float S1 = 0.f, S2 = 0.f;
#pragma unroll
        for (int ws = 0; ws < 8; ws++) { S1 += st_s[(ws * 128 + tid) * 2]; S2 += st_s[(ws * 128 + tid) * 2 + 1]; }
        const float mean = S1 / (float)C;
        float var = S2 / (float)C - mean * mean; var = fmaxf(var, 0.f);
        p.stats[2 * t] = mean; p.stats[2 * t + 1] = rsqrtf(var + p.ln_eps);
      }
    }
    __syncthreads();
  }
}

// ---------------------------------------------------------------- GEMM phases
template <int BM, int BN, int TM, int TN, int PHASE>
__device__ void gemm_phase(const Params& p, float* smem, float* sq_s, float* inv_s, float* red_s) {
  constexpr int AQ = BM / 32, BQ = BN / 32, BND = BN / 4;
  float* As = smem;              // [2][BK][BM]
  float* Bs = smem + 2 * BK * BM; // [2][BK][BN]
  const int tid = threadIdx.x, ty = tid >> 4, tx = tid & 15, warp = tid >> 5, lane = tid & 31;
  const int M = p.M, HW = p.HW;
  const int N = (PHASE == 2) ? p.C4 : p.C;
  const int K = (PHASE == 2) ? p.C : p.C4;
  const float* __restrict__ Ag = (PHASE == 2) ? p.xn : p.hidden;
  const float* __restrict__ Bg = (PHASE == 2) ? p.w1t : p.w2t;
  const int mt = (M + BM - 1) / BM, nt = (N + BN - 1) / BN;
  const int ntiles = mt * nt, nk = K / BK;
  const int a_r = tid >> 3, a_k = (tid & 7) * 4;

  for (int tile = blockIdx.x; tile < ntiles; tile += gridDim.x) {
    const int m0 = (tile / nt) * BM, n0 = (tile - (tile / nt) * nt) * BN;
    const int b_first = m0 / HW;
    const int nimg = min(MAXIMG, (min(m0 + BM, M) - 1) / HW - b_first + 1);

    int arow[AQ]; bool aval[AQ]; float rc0[AQ], rc1[AQ]; int aimg[AQ];
#pragma unroll
    for (int q = 0; q < AQ; q++) {
      arow[q] = m0 + q * 32 + a_r; aval[q] = arow[q] < M;
      const int rr = aval[q] ? arow[q] : 0;
      if (PHASE == 2) { rc0[q] = p.stats[2 * rr]; rc1[q] = p.stats[2 * rr + 1]; aimg[q] = 0; }
      else { aimg[q] = rr / HW - b_first; rc0[q] = 0.f; rc1[q] = 0.f; }
    }
    if (PHASE == 3) {
      for (int img = 0; img < nimg; img++) {
        const float* sq = p.sumsq + (size_t)(b_first + img) * K;
        float s = 0.f;
        for (int k = tid; k < K; k += NT) s += sqrtf(sq[k]);
        s = warp_sum(s);
        if (lane == 0) red_s[warp] = s;
        __syncthreads();
        if (tid == 0) {
          float tot = 0.f;
#pragma unroll
          for (int ws = 0; ws < 8; ws++) tot += red_s[ws];
          inv_s[img] = 1.f / (tot / (float)K + p.eps);
        }
        __syncthreads();
      }
    }

    float acc[TM][TN];
#pragma unroll
    for (int i = 0; i < TM; i++)
#pragma unroll
      for (int j = 0; j < TN; j++) acc[i][j] = 0.f;

    float4 ra[AQ], rb[BQ];
    auto load_chunk = [&](int kc) {
      const int k0 = kc * BK;
#pragma unroll
      for (int q = 0; q < AQ; q++) {
        float4 v = make_float4(0.f, 0.f, 0.f, 0.f);
        if (aval[q]) {
          v = __ldg(reinterpret_cast<const float4*>(Ag + (size_t)arow[q] * K + k0 + a_k));
          if (PHASE == 2) {
            const float4 lw = __ldg(reinterpret_cast<const float4*>(p.lnw + k0 + a_k));
            const float4 lb = __ldg(reinterpret_cast<const float4*>(p.lnb + k0 + a_k));
            const float mr = rc0[q], rs = rc1[q];
            v.x = fmaf((v.x - mr) * rs, lw.x, lb.x); v.y = fmaf((v.y - mr) * rs, lw.y, lb.y);
            v.z = fmaf((v.z - mr) * rs, lw.z, lb.z); v.w = fmaf((v.w - mr) * rs, lw.w, lb.w);
          } else {
            const float4 gw = __ldg(reinterpret_cast<const float4*>(p.gw + k0 + a_k));
            const float4 gb = __ldg(reinterpret_cast<const float4*>(p.gb + k0 + a_k));
            const float4 sq = __ldg(reinterpret_cast<const float4*>(p.sumsq + (size_t)(b_first + aimg[q]) * K + k0 + a_k));
            const float inv = inv_s[aimg[q]];
            v.x = fmaf(v.x, fmaf(gw.x * inv, sqrtf(sq.x), 1.f), gb.x);
            v.y = fmaf(v.y, fmaf(gw.y * inv, sqrtf(sq.y), 1.f), gb.y);
            v.z = fmaf(v.z, fmaf(gw.z * inv, sqrtf(sq.z), 1.f), gb.z);
            v.w = fmaf(v.w, fmaf(gw.w * inv, sqrtf(sq.w), 1.f), gb.w);
          }
        }
        ra[q] = v;
      }
#pragma unroll
      for (int q = 0; q < BQ; q++) {
        const int id = q * NT + tid, krow = id / BND, nq = (id - krow * BND) * 4;
        const int col = n0 + nq;
        rb[q] = (col < N) ? __ldg(reinterpret_cast<const float4*>(Bg + (size_t)(k0 + krow) * N + col))
                          : make_float4(0.f, 0.f, 0.f, 0.f);
      }
    };
    auto store_regs = [&](int buf) {
#pragma unroll
      for (int q = 0; q < AQ; q++) {
        float* dst = As + (buf * BK + a_k) * BM + q * 32 + a_r;
        dst[0] = ra[q].x; dst[BM] = ra[q].y; dst[2 * BM] = ra[q].z; dst[3 * BM] = ra[q].w;
      }
#pragma unroll
      for (int q = 0; q < BQ; q++) {
        const int id = q * NT + tid, krow = id / BND, nq = (id - krow * BND) * 4;
        *reinterpret_cast<float4*>(Bs + (buf * BK + krow) * BN + nq) = rb[q];
      }
    };

    load_chunk(0);
    store_regs(0);
    __syncthreads();
    for (int kc = 0; kc < nk; kc++) {
      const int buf = kc & 1;
      if (kc + 1 < nk) load_chunk(kc + 1);
      const float* Ab = As + buf * BK * BM + ty * TM;
      const float* Bb = Bs + buf * BK * BN + tx * TN;
#pragma unroll 4
      for (int k = 0; k < BK; k++) {
        float a[TM], b[TN];
        if (TM == 8) {
          const float4 a0 = *reinterpret_cast<const float4*>(Ab + k * BM);
          const float4 a1 = *reinterpret_cast<const float4*>(Ab + k * BM + 4);
          a[0] = a0.x; a[1] = a0.y; a[2] = a0.z; a[3] = a0.w; a[4] = a1.x; a[5] = a1.y; a[6] = a1.z; a[7] = a1.w;
        } else if (TM == 4) {
          const float4 a0 = *reinterpret_cast<const float4*>(Ab + k * BM);
          a[0] = a0.x; a[1] = a0.y; a[2] = a0.z; a[3] = a0.w;
        } else {
          const float2 a0 = *reinterpret_cast<const float2*>(Ab + k * BM);
          a[0] = a0.x; a[1] = a0.y;
        }
        if (TN == 8) {
          const float4 b0 = *reinterpret_cast<const float4*>(Bb + k * BN);
          const float4 b1 = *reinterpret_cast<const float4*>(Bb + k * BN + 4);
          b[0] = b0.x; b[1] = b0.y; b[2] = b0.z; b[3] = b0.w; b[4] = b1.x; b[5] = b1.y; b[6] = b1.z; b[7] = b1.w;
        } else if (TN == 4) {
          const float4 b0 = *reinterpret_cast<const float4*>(Bb + k * BN);
          b[0] = b0.x; b[1] = b0.y; b[2] = b0.z; b[3] = b0.w;
        } else {
          const float2 b0 = *reinterpret_cast<const float2*>(Bb + k * BN);
          b[0] = b0.x; b[1] = b0.y;
        }
#pragma unroll
        for (int i = 0; i < TM; i++)
#pragma unroll
          for (int j = 0; j < TN; j++) acc[i][j] = fmaf(a[i], b[j], acc[i][j]);
      }
      if (kc + 1 < nk) store_regs(buf ^ 1);
      __syncthreads();
    }

    if (PHASE == 2) {
      float bia[TN];
#pragma unroll
      for (int j = 0; j < TN; j++) bia[j] = __ldg(p.b1 + n0 + tx * TN + j);
      float csum[TN];
#pragma unroll
      for (int j = 0; j < TN; j++) csum[j] = 0.f;
      int cur = -1;
#pragma unroll
      for (int i = 0; i < TM; i++) {
        const int row = m0 + ty * TM + i;
        if (row < M) {
          const int img = row / HW;
          if (img != cur) {
            if (cur >= 0) {
              const int il = cur - b_first;
#pragma unroll
              for (int j = 0; j < TN; j++) {
                if (il < MAXIMG) atomicAdd(&sq_s[il * BN + tx * TN + j], csum[j]);
                else atomicAdd(p.sumsq + (size_t)cur * N + n0 + tx * TN + j, csum[j]);
                csum[j] = 0.f;
              }
            }
            cur = img;
          }
          float g[TN];
#pragma unroll
          for (int j = 0; j < TN; j++) { g[j] = gelu_f(acc[i][j] + bia[j]); csum[j] = fmaf(g[j], g[j], csum[j]); }
          float* dst = p.hidden + (size_t)row * N + n0 + tx * TN;
          if (TN == 8) {
            *reinterpret_cast<float4*>(dst) = make_float4(g[0], g[1], g[2], g[3]);
            *reinterpret_cast<float4*>(dst + 4) = make_float4(g[4], g[5], g[6], g[7]);
          } else if (TN == 4) {
            *reinterpret_cast<float4*>(dst) = make_float4(g[0], g[1], g[2], g[3]);
          } else {
            *reinterpret_cast<float2*>(dst) = make_float2(g[0], g[1]);
          }
        }
      }
      if (cur >= 0) {
        const int il = cur - b_first;
#pragma unroll
        for (int j = 0; j < TN; j++) {
          if (il < MAXIMG) atomicAdd(&sq_s[il * BN + tx * TN + j], csum[j]);
          else atomicAdd(p.sumsq + (size_t)cur * N + n0 + tx * TN + j, csum[j]);
        }
      }
      __syncthreads();
      for (int idx = tid; idx < nimg * BN; idx += NT) {
        const int img = idx / BN, n = idx - img * BN;
        const float v = sq_s[idx]; sq_s[idx] = 0.f;
        atomicAdd(p.sumsq + (size_t)(b_first + img) * N + n0 + n, v);
      }
    } else {
      // transpose through smem, then write NCHW with residual + bias
      float* Cs = smem;  // [BN][BM+1]
#pragma unroll
      for (int i = 0; i < TM; i++)
#pragma unroll
        for (int j = 0; j < TN; j++) Cs[(tx * TN + j) * (BM + 1) + ty * TM + i] = acc[i][j];
      __syncthreads();
      const int hw_first = m0 - b_first * HW;
      for (int nl = warp; nl < BN; nl += 8) {
        const int col = n0 + nl;
        if (col >= N) break;
        const float bias = __ldg(p.b2 + col);
        int b = b_first, hw = hw_first + lane;
        while (hw >= HW) { hw -= HW; b++; }
#pragma unroll
        for (int jj = 0; jj < BM / 32; jj++) {
          const int ml = lane + 32 * jj, row = m0 + ml;
          if (row < M) {
            const size_t idx = ((size_t)b * N + col) * HW + hw;
            p.out[idx] = Cs[nl * (BM + 1) + ml] + bias + __ldg(p.x + idx);
          }
          hw += 32;
          while (hw >= HW) { hw -= HW; b++; }
        }
      }
      __syncthreads();
    }
  }
}

__global__ void __launch_bounds__(NT, 2) convnext_fused(Params p) {
  extern __shared__ float4 smem4[];
  float* smem = reinterpret_cast<float*>(smem4);
  float* sq_s = smem + GEMM_SMEM_FLOATS;
  float* inv_s = sq_s + MAXIMG * 128;
  float* red_s = inv_s + 8;
  for (int i = threadIdx.x; i < MAXIMG * 128; i += NT) sq_s[i] = 0.f;
  __syncthreads();
  cg::grid_group grid = cg::this_grid();

  phase1(p, smem);
  grid.sync();
  switch (p.cfg2) {
    case 0: gemm_phase<128, 128, 8, 8, 2>(p, smem, sq_s, inv_s, red_s); break;
    case 1: gemm_phase<64, 64, 4, 4, 2>(p, smem, sq_s, inv_s, red_s); break;
    default: gemm_phase<32, 32, 2, 2, 2>(p, smem, sq_s, inv_s, red_s); break;
  }
  grid.sync();
  switch (p.cfg3) {
    case 0: gemm_phase<128, 128, 8, 8, 3>(p, smem, sq_s, inv_s, red_s); break;
    case 1: gemm_phase<64, 64, 4, 4, 3>(p, smem, sq_s, inv_s, red_s); break;
    default: gemm_phase<32, 32, 2, 2, 3>(p, smem, sq_s, inv_s, red_s); break;
  }
}

static int pick_cfg(long M, long N, int grid) {
  const long t128 = ((M + 127) / 128) * ((N + 127) / 128);
  const long t64 = ((M + 63) / 64) * ((N + 63) / 64);
  if (t128 >= 2L * grid) return 0;
  if (t64 >= 2L * grid) return 1;
  return 2;
}

extern "C" const char* convnext_launch(Params p, void* stream_v) {
  static int grid_size = 0;
  cudaError_t e;
  if (grid_size == 0) {
    e = cudaFuncSetAttribute(convnext_fused, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_BYTES);
    if (e != cudaSuccess) return cudaGetErrorString(e);
    int dev = 0; cudaGetDevice(&dev);
    int sms = 0; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, dev);
    int bps = 0;
    e = cudaOccupancyMaxActiveBlocksPerMultiprocessor(&bps, convnext_fused, NT, SMEM_BYTES);
    if (e != cudaSuccess) return cudaGetErrorString(e);
    if (bps < 1) bps = 1;
    grid_size = sms * bps;
  }
  p.cfg2 = pick_cfg(p.M, p.C4, grid_size);
  p.cfg3 = pick_cfg(p.M, p.C, grid_size);
  if (p.W >= 32) {
    p.p1_mode = 1; p.p1_hq = (p.H + 3) / 4; p.p1_wq = (p.W + 31) / 32;
    p.p1_tiles = p.B * p.p1_hq * p.p1_wq;
  } else {
    p.p1_mode = 0; p.p1_hq = 0; p.p1_wq = 0;
    p.p1_tiles = (p.M + 127) / 128;
  }
  void* args[] = {&p};
  e = cudaLaunchCooperativeKernel((const void*)convnext_fused, dim3(grid_size), dim3(NT), args, (size_t)SMEM_BYTES,
                                  (cudaStream_t)stream_v);
  if (e != cudaSuccess) return cudaGetErrorString(e);
  return nullptr;
}

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <stdexcept>
#include <string>

struct Params {
  const float* x; const float* dww; const float* dwb; const float* lnw; const float* lnb;
  const float* w1; const float* b1; const float* gw; const float* gb; const float* w2; const float* b2;
  float* out;
  float* xn; float* stats; float* hidden; float* sumsq; float* w1t; float* w2t;
  int B, C, H, W, HW, M, C4;
  float eps, ln_eps;
  int p1_mode, p1_tiles, p1_hq, p1_wq;
  int cfg2, cfg3;
};
extern "C" const char* convnext_launch(Params p, void* stream);

static inline size_t align256(size_t v) { return (v + 255) & ~(size_t)255; }

void run(torch::Tensor x, torch::Tensor dwconv_weight, torch::Tensor dwconv_bias, torch::Tensor layernorm_weight,
         torch::Tensor layernorm_bias, torch::Tensor pwconv1_weight, torch::Tensor pwconv1_bias, torch::Tensor grn_weight,
         torch::Tensor grn_bias, torch::Tensor pwconv2_weight, torch::Tensor pwconv2_bias, double eps, double layer_norm_eps,
         torch::Tensor output) {
  TORCH_CHECK(x.is_cuda() && x.dtype() == torch::kFloat32 && x.is_contiguous(), "x must be contiguous fp32 cuda");
  TORCH_CHECK(output.is_contiguous() && output.dtype() == torch::kFloat32, "output must be contiguous fp32");
  TORCH_CHECK(x.dim() == 4, "x must be NCHW");
  const c10::cuda::OptionalCUDAGuard guard(x.device());
  const int B = (int)x.size(0), C = (int)x.size(1), H = (int)x.size(2), W = (int)x.size(3);
  TORCH_CHECK(C % 32 == 0, "dim must be a multiple of 32");
  TORCH_CHECK(H * W >= 32, "H*W must be >= 32");
  const int HW = H * W, M = B * HW, C4 = 4 * C;
  TORCH_CHECK(pwconv1_weight.is_contiguous() && pwconv2_weight.is_contiguous() && dwconv_weight.is_contiguous(), "weights must be contiguous");
  TORCH_CHECK(layernorm_weight.is_contiguous() && layernorm_bias.is_contiguous() && grn_weight.is_contiguous() && grn_bias.is_contiguous(), "params contiguous");
  TORCH_CHECK(dwconv_bias.is_contiguous() && pwconv1_bias.is_contiguous() && pwconv2_bias.is_contiguous(), "biases contiguous");

  // workspace (no state kept across calls)
  const size_t off_xn = 0;
  const size_t off_stats = align256(off_xn + (size_t)M * C * 4);
  const size_t off_hidden = align256(off_stats + (size_t)M * 2 * 4);
  const size_t off_sumsq = align256(off_hidden + (size_t)M * C4 * 4);
  const size_t off_w1t = align256(off_sumsq + (size_t)B * C4 * 4);
  const size_t off_w2t = align256(off_w1t + (size_t)C * C4 * 4);
  const size_t total = align256(off_w2t + (size_t)C4 * C * 4);
  torch::Tensor ws = torch::empty({(long)total}, x.options().dtype(torch::kUInt8));
  char* wp = (char*)ws.data_ptr();

  Params p;
  p.x = x.data_ptr<float>(); p.dww = dwconv_weight.data_ptr<float>(); p.dwb = dwconv_bias.data_ptr<float>();
  p.lnw = layernorm_weight.data_ptr<float>(); p.lnb = layernorm_bias.data_ptr<float>();
  p.w1 = pwconv1_weight.data_ptr<float>(); p.b1 = pwconv1_bias.data_ptr<float>();
  p.gw = grn_weight.data_ptr<float>(); p.gb = grn_bias.data_ptr<float>();
  p.w2 = pwconv2_weight.data_ptr<float>(); p.b2 = pwconv2_bias.data_ptr<float>();
  p.out = output.data_ptr<float>();
  p.xn = (float*)(wp + off_xn); p.stats = (float*)(wp + off_stats); p.hidden = (float*)(wp + off_hidden);
  p.sumsq = (float*)(wp + off_sumsq); p.w1t = (float*)(wp + off_w1t); p.w2t = (float*)(wp + off_w2t);
  p.B = B; p.C = C; p.H = H; p.W = W; p.HW = HW; p.M = M; p.C4 = C4;
  p.eps = (float)eps; p.ln_eps = (float)layer_norm_eps;
  p.p1_mode = 0; p.p1_tiles = 0; p.p1_hq = 0; p.p1_wq = 0; p.cfg2 = 0; p.cfg3 = 0;

  cudaStream_t stream = at::cuda::getCurrentCUDAStream(x.device().index()).stream();
  const char* err = convnext_launch(p, (void*)stream);
  if (err != nullptr) throw std::runtime_error(std::string("convnext_launch failed: ") + err);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) { m.def("run", &run, "ConvNeXtV2 block with GRN (fused, fp32)"); }

// ConvNeXtV2 block with GRN: one cooperative launch, three phases, fp32 SIMT.
//  P1: depthwise 7x7 conv (+bias) -> xn [M][C] (channels-last), per-token LN stats; zero GRN sums; transpose weights
//  P2: hidden = gelu(LN(xn) @ W1^T + b1) -> [M][4C]; sumsq[b][k] += hidden^2 (per image)
//  P3: out = x + (hidden * (1 + gw*nf) + gb) @ W2^T + b2, written NCHW
#include <cuda_runtime.h>
#include <cooperative_groups.h>
#include <stdint.h>
namespace cg = cooperative_groups;

#define NT 256
#define BK 32
#define MAXIMG 5
#define GEMM_SMEM_FLOATS (128 * 129)
#define SMEM_BYTES (GEMM_SMEM_FLOATS * 4 + MAXIMG * 128 * 4 + 64)

struct Params {
  const float* x; const float* dww; const float* dwb; const float* lnw; const float* lnb;
  const float* w1; const float* b1; const float* gw; const float* gb; const float* w2; const float* b2;
  float* out;
  float* xn; float* stats; float* hidden; float* sumsq; float* w1t; float* w2t;
  int B, C, H, W, HW, M, C4;
  float eps, ln_eps;
  int p1_mode, p1_tiles, p1_hq, p1_wq;
  int cfg2, cfg3;
};

__device__ __forceinline__ float gelu_f(float v) { return 0.5f * v * (1.f + erff(v * 0.70710678118654752f)); }

__device__ __forceinline__ float warp_sum(float v) {
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffffu, v, o);
  return v;
}

// ---------------------------------------------------------------- phase 1 helpers
__device__ void transpose_mat(const float* __restrict__ src, int R, int Cc, float* __restrict__ dst, float* tile) {
  // src [R][Cc] -> dst [Cc][R]
  const int rt = (R + 31) / 32, ct = (Cc + 31) / 32;
  const int tid = threadIdx.x, j = tid & 31, i0 = tid >> 5;
  for (int t = blockIdx.x; t < rt * ct; t += gridDim.x) {
    const int tr = t / ct, tc = t % ct;
#pragma unroll
    for (int s = 0; s < 4; s++) {
      const int i = i0 + 8 * s, r = tr * 32 + i, c = tc * 32 + j;
      tile[i * 33 + j] = (r < R && c < Cc) ? src[(size_t)r * Cc + c] : 0.f;
    }
    __syncthreads();
#pragma unroll
    for (int s = 0; s < 4; s++) {
      const int i = i0 + 8 * s, c = tc * 32 + i, r = tr * 32 + j;
      if (r < R && c < Cc) dst[(size_t)c * R + r] = tile[j * 33 + i];
    }
    __syncthreads();
  }
}

__device__ void phase1(const Params& p, float* smem) {
  const int tid = threadIdx.x, warp = tid >> 5, lane = tid & 31;
  const int C = p.C, H = p.H, W = p.W, HW = p.HW, M = p.M;
  // zero GRN sums
  for (int i = blockIdx.x * NT + tid; i < p.B * p.C4; i += gridDim.x * NT) p.sumsq[i] = 0.f;
  // weight transposes
  transpose_mat(p.w1, p.C4, C, p.w1t, smem);
  transpose_mat(p.w2, C, p.C4, p.w2t, smem);

  float* Xs = smem;                       // [32][129]
  float* st_s = smem + 32 * 129;          // [8][128][2]
  int* tok_s = (int*)(st_s + 8 * 128 * 2);  // [128]

  for (int tile = blockIdx.x; tile < p.p1_tiles; tile += gridDim.x) {
    int tok[4], bb[4], hh[4], ww[4]; bool val[4];
    int nb = 0, h0 = 0, w = 0;
    if (p.p1_mode == 1) {
      const int per = p.p1_hq * p.p1_wq;
      nb = tile / per; const int rem = tile - nb * per;
      const int hq = rem / p.p1_wq, wqi = rem - hq * p.p1_wq;
      w = wqi * 32 + lane; h0 = hq * 4;
#pragma unroll
      for (int r = 0; r < 4; r++) {
        const int h = h0 + r;
        val[r] = (w < W) && (h < H);
        tok[r] = nb * HW + h * W + w; bb[r] = nb; hh[r] = h; ww[r] = w;
      }
    } else {
#pragma unroll
      for (int r = 0; r < 4; r++) {
        const int t = tile * 128 + r * 32 + lane;
        val[r] = t < M;
        const int tt = val[r] ? t : 0;
        const int b = tt / HW; const int rem = tt - b * HW; const int h = rem / W;
        tok[r] = t; bb[r] = b; hh[r] = h; ww[r] = rem - h * W;
      }
    }
    if (tid < 128) {
      const int r = tid >> 5;
      tok_s[tid] = val[r] ? tok[r] : -1;
    }
    float s1[4] = {0.f, 0.f, 0.f, 0.f}, s2[4] = {0.f, 0.f, 0.f, 0.f};

    for (int cc = 0; cc < C / 32; cc++) {
#pragma unroll 1
      for (int cl = 0; cl < 4; cl++) {
        const int c = cc * 32 + warp * 4 + cl;
        const float* wk = p.dww + (size_t)c * 49;
        float acc[4] = {0.f, 0.f, 0.f, 0.f};
        if (p.p1_mode == 1) {
          const float* xc = p.x + ((size_t)nb * C + c) * HW;
#pragma unroll 1
          for (int j = 0; j < 7; j++) {
            const int ww2 = w + j - 3;
            const bool okw = (ww2 >= 0) && (ww2 < W);
            float wt[7], v[10];
#pragma unroll
            for (int i = 0; i < 7; i++) wt[i] = __ldg(wk + i * 7 + j);
#pragma unroll
            for (int i = 0; i < 10; i++) {
              const int hh2 = h0 - 3 + i;
              v[i] = (okw && hh2 >= 0 && hh2 < H) ? __ldg(xc + hh2 * W + ww2) : 0.f;
            }
#pragma unroll
            for (int r = 0; r < 4; r++)
#pragma unroll
              for (int i = 0; i < 7; i++) acc[r] = fmaf(v[r + i], wt[i], acc[r]);
          }
        } else {
#pragma unroll 1
          for (int i = 0; i < 7; i++) {
#pragma unroll 1
            for (int j = 0; j < 7; j++) {
              const float wt = __ldg(wk + i * 7 + j);
#pragma unroll
              for (int r = 0; r < 4; r++) {
                const int hh2 = hh[r] - 3 + i, ww2 = ww[r] - 3 + j;
                if (val[r] && hh2 >= 0 && hh2 < H && ww2 >= 0 && ww2 < W)
                  acc[r] = fmaf(__ldg(p.x + ((size_t)bb[r] * C + c) * HW + hh2 * W + ww2), wt, acc[r]);
              }
            }
          }
        }
        const float bias = __ldg(p.dwb + c);
#pragma unroll
        for (int r = 0; r < 4; r++) {
          const float v = val[r] ? acc[r] + bias : 0.f;
          Xs[(warp * 4 + cl) * 129 + r * 32 + lane] = v;
          s1[r] += v; s2[r] = fmaf(v, v, s2[r]);
        }
      }
      __syncthreads();
      {
        const int slot = tid >> 1, half = tid & 1;
        const int t = tok_s[slot];
        if (t >= 0) {
          float* base = p.xn + (size_t)t * C + cc * 32 + half * 16;
#pragma unroll
          for (int j = 0; j < 4; j++) {
            const int c0 = half * 16 + 4 * j;
            float4 v;
            v.x = Xs[(c0 + 0) * 129 + slot]; v.y = Xs[(c0 + 1) * 129 + slot];
            v.z = Xs[(c0 + 2) * 129 + slot]; v.w = Xs[(c0 + 3) * 129 + slot];
            *reinterpret_cast<float4*>(base + 4 * j) = v;
          }
        }
      }
      __syncthreads();
    }
#pragma unroll
    for (int r = 0; r < 4; r++) {
      st_s[(warp * 128 + r * 32 + lane) * 2 + 0] = s1[r];
      st_s[(warp * 128 + r * 32 + lane) * 2 + 1] = s2[r];
    }
    __syncthreads();
    if (tid < 128) {
      const int t = tok_s[tid];
      if (t >= 0) {
        float S1 = 0.f, S2 = 0.f;
#pragma unroll
        for (int ws = 0; ws < 8; ws++) { S1 += st_s[(ws * 128 + tid) * 2]; S2 += st_s[(ws * 128 + tid) * 2 + 1]; }
        const float mean = S1 / (float)C;
        float var = S2 / (float)C - mean * mean; var = fmaxf(var, 0.f);
        p.stats[2 * t] = mean; p.stats[2 * t + 1] = rsqrtf(var + p.ln_eps);
      }
    }
    __syncthreads();
  }
}

// ---------------------------------------------------------------- GEMM phases
template <int BM, int BN, int TM, int TN, int PHASE>
__device__ void gemm_phase(const Params& p, float* smem, float* sq_s, float* inv_s, float* red_s) {
  constexpr int AQ = BM / 32, BQ = BN / 32, BND = BN / 4;
  float* As = smem;              // [2][BK][BM]
  float* Bs = smem + 2 * BK * BM; // [2][BK][BN]
  const int tid = threadIdx.x, ty = tid >> 4, tx = tid & 15, warp = tid >> 5, lane = tid & 31;
  const int M = p.M, HW = p.HW;
  const int N = (PHASE == 2) ? p.C4 : p.C;
  const int K = (PHASE == 2) ? p.C : p.C4;
  const float* __restrict__ Ag = (PHASE == 2) ? p.xn : p.hidden;
  const float* __restrict__ Bg = (PHASE == 2) ? p.w1t : p.w2t;
  const int mt = (M + BM - 1) / BM, nt = (N + BN - 1) / BN;
  const int ntiles = mt * nt, nk = K / BK;
  const int a_r = tid >> 3, a_k = (tid & 7) * 4;

  for (int tile = blockIdx.x; tile < ntiles; tile += gridDim.x) {
    const int m0 = (tile / nt) * BM, n0 = (tile - (tile / nt) * nt) * BN;
    const int b_first = m0 / HW;
    const int nimg = min(MAXIMG, (min(m0 + BM, M) - 1) / HW - b_first + 1);

    int arow[AQ]; bool aval[AQ]; float rc0[AQ], rc1[AQ]; int aimg[AQ];
#pragma unroll
    for (int q = 0; q < AQ; q++) {
      arow[q] = m0 + q * 32 + a_r; aval[q] = arow[q] < M;
      const int rr = aval[q] ? arow[q] : 0;
      if (PHASE == 2) { rc0[q] = p.stats[2 * rr]; rc1[q] = p.stats[2 * rr + 1]; aimg[q] = 0; }
      else { aimg[q] = rr / HW - b_first; rc0[q] = 0.f; rc1[q] = 0.f; }
    }
    if (PHASE == 3) {
      for (int img = 0; img < nimg; img++) {
        const float* sq = p.sumsq + (size_t)(b_first + img) * K;
        float s = 0.f;
        for (int k = tid; k < K; k += NT) s += sqrtf(sq[k]);
        s = warp_sum(s);
        if (lane == 0) red_s[warp] = s;
        __syncthreads();
        if (tid == 0) {
          float tot = 0.f;
#pragma unroll
          for (int ws = 0; ws < 8; ws++) tot += red_s[ws];
          inv_s[img] = 1.f / (tot / (float)K + p.eps);
        }
        __syncthreads();
      }
    }

    float acc[TM][TN];
#pragma unroll
    for (int i = 0; i < TM; i++)
#pragma unroll
      for (int j = 0; j < TN; j++) acc[i][j] = 0.f;

    float4 ra[AQ], rb[BQ];
    auto load_chunk = [&](int kc) {
      const int k0 = kc * BK;
#pragma unroll
      for (int q = 0; q < AQ; q++) {
        float4 v = make_float4(0.f, 0.f, 0.f, 0.f);
        if (aval[q]) {
          v = __ldg(reinterpret_cast<const float4*>(Ag + (size_t)arow[q] * K + k0 + a_k));
          if (PHASE == 2) {
            const float4 lw = __ldg(reinterpret_cast<const float4*>(p.lnw + k0 + a_k));
            const float4 lb = __ldg(reinterpret_cast<const float4*>(p.lnb + k0 + a_k));
            const float mr = rc0[q], rs = rc1[q];
            v.x = fmaf((v.x - mr) * rs, lw.x, lb.x); v.y = fmaf((v.y - mr) * rs, lw.y, lb.y);
            v.z = fmaf((v.z - mr) * rs, lw.z, lb.z); v.w = fmaf((v.w - mr) * rs, lw.w, lb.w);
          } else {
            const float4 gw = __ldg(reinterpret_cast<const float4*>(p.gw + k0 + a_k));
            const float4 gb = __ldg(reinterpret_cast<const float4*>(p.gb + k0 + a_k));
            const float4 sq = __ldg(reinterpret_cast<const float4*>(p.sumsq + (size_t)(b_first + aimg[q]) * K + k0 + a_k));
            const float inv = inv_s[aimg[q]];
            v.x = fmaf(v.x, fmaf(gw.x * inv, sqrtf(sq.x), 1.f), gb.x);
            v.y = fmaf(v.y, fmaf(gw.y * inv, sqrtf(sq.y), 1.f), gb.y);
            v.z = fmaf(v.z, fmaf(gw.z * inv, sqrtf(sq.z), 1.f), gb.z);
            v.w = fmaf(v.w, fmaf(gw.w * inv, sqrtf(sq.w), 1.f), gb.w);
          }
        }
        ra[q] = v;
      }
#pragma unroll
      for (int q = 0; q < BQ; q++) {
        const int id = q * NT + tid, krow = id / BND, nq = (id - krow * BND) * 4;
        const int col = n0 + nq;
        rb[q] = (col < N) ? __ldg(reinterpret_cast<const float4*>(Bg + (size_t)(k0 + krow) * N + col))
                          : make_float4(0.f, 0.f, 0.f, 0.f);
      }
    };
    auto store_regs = [&](int buf) {
#pragma unroll
      for (int q = 0; q < AQ; q++) {
        float* dst = As + (buf * BK + a_k) * BM + q * 32 + a_r;
        dst[0] = ra[q].x; dst[BM] = ra[q].y; dst[2 * BM] = ra[q].z; dst[3 * BM] = ra[q].w;
      }
#pragma unroll
      for (int q = 0; q < BQ; q++) {
        const int id = q * NT + tid, krow = id / BND, nq = (id - krow * BND) * 4;
        *reinterpret_cast<float4*>(Bs + (buf * BK + krow) * BN + nq) = rb[q];
      }
    };

    load_chunk(0);
    store_regs(0);
    __syncthreads();
    for (int kc = 0; kc < nk; kc++) {
      const int buf = kc & 1;
      if (kc + 1 < nk) load_chunk(kc + 1);
      const float* Ab = As + buf * BK * BM + ty * TM;
      const float* Bb = Bs + buf * BK * BN + tx * TN;
#pragma unroll 4
      for (int k = 0; k < BK; k++) {
        float a[TM], b[TN];
        if (TM == 8) {
          const float4 a0 = *reinterpret_cast<const float4*>(Ab + k * BM);
          const float4 a1 = *reinterpret_cast<const float4*>(Ab + k * BM + 4);
          a[0] = a0.x; a[1] = a0.y; a[2] = a0.z; a[3] = a0.w; a[4] = a1.x; a[5] = a1.y; a[6] = a1.z; a[7] = a1.w;
        } else if (TM == 4) {
          const float4 a0 = *reinterpret_cast<const float4*>(Ab + k * BM);
          a[0] = a0.x; a[1] = a0.y; a[2] = a0.z; a[3] = a0.w;
        } else {
          const float2 a0 = *reinterpret_cast<const float2*>(Ab + k * BM);
          a[0] = a0.x; a[1] = a0.y;
        }
        if (TN == 8) {
          const float4 b0 = *reinterpret_cast<const float4*>(Bb + k * BN);
          const float4 b1 = *reinterpret_cast<const float4*>(Bb + k * BN + 4);
          b[0] = b0.x; b[1] = b0.y; b[2] = b0.z; b[3] = b0.w; b[4] = b1.x; b[5] = b1.y; b[6] = b1.z; b[7] = b1.w;
        } else if (TN == 4) {
          const float4 b0 = *reinterpret_cast<const float4*>(Bb + k * BN);
          b[0] = b0.x; b[1] = b0.y; b[2] = b0.z; b[3] = b0.w;
        } else {
          const float2 b0 = *reinterpret_cast<const float2*>(Bb + k * BN);
          b[0] = b0.x; b[1] = b0.y;
        }
#pragma unroll
        for (int i = 0; i < TM; i++)
#pragma unroll
          for (int j = 0; j < TN; j++) acc[i][j] = fmaf(a[i], b[j], acc[i][j]);
      }
      if (kc + 1 < nk) store_regs(buf ^ 1);
      __syncthreads();
    }

    if (PHASE == 2) {
      float bia[TN];
#pragma unroll
      for (int j = 0; j < TN; j++) bia[j] = __ldg(p.b1 + n0 + tx * TN + j);
      float csum[TN];
#pragma unroll
      for (int j = 0; j < TN; j++) csum[j] = 0.f;
      int cur = -1;
#pragma unroll
      for (int i = 0; i < TM; i++) {
        const int row = m0 + ty * TM + i;
        if (row < M) {
          const int img = row / HW;
          if (img != cur) {
            if (cur >= 0) {
              const int il = cur - b_first;
#pragma unroll
              for (int j = 0; j < TN; j++) {
                if (il < MAXIMG) atomicAdd(&sq_s[il * BN + tx * TN + j], csum[j]);
                else atomicAdd(p.sumsq + (size_t)cur * N + n0 + tx * TN + j, csum[j]);
                csum[j] = 0.f;
              }
            }
            cur = img;
          }
          float g[TN];
#pragma unroll
          for (int j = 0; j < TN; j++) { g[j] = gelu_f(acc[i][j] + bia[j]); csum[j] = fmaf(g[j], g[j], csum[j]); }
          float* dst = p.hidden + (size_t)row * N + n0 + tx * TN;
          if (TN == 8) {
            *reinterpret_cast<float4*>(dst) = make_float4(g[0], g[1], g[2], g[3]);
            *reinterpret_cast<float4*>(dst + 4) = make_float4(g[4], g[5], g[6], g[7]);
          } else if (TN == 4) {
            *reinterpret_cast<float4*>(dst) = make_float4(g[0], g[1], g[2], g[3]);
          } else {
            *reinterpret_cast<float2*>(dst) = make_float2(g[0], g[1]);
          }
        }
      }
      if (cur >= 0) {
        const int il = cur - b_first;
#pragma unroll
        for (int j = 0; j < TN; j++) {
          if (il < MAXIMG) atomicAdd(&sq_s[il * BN + tx * TN + j], csum[j]);
          else atomicAdd(p.sumsq + (size_t)cur * N + n0 + tx * TN + j, csum[j]);
        }
      }
      __syncthreads();
      for (int idx = tid; idx < nimg * BN; idx += NT) {
        const int img = idx / BN, n = idx - img * BN;
        const float v = sq_s[idx]; sq_s[idx] = 0.f;
        atomicAdd(p.sumsq + (size_t)(b_first + img) * N + n0 + n, v);
      }
    } else {
      // transpose through smem, then write NCHW with residual + bias
      float* Cs = smem;  // [BN][BM+1]
#pragma unroll
      for (int i = 0; i < TM; i++)
#pragma unroll
        for (int j = 0; j < TN; j++) Cs[(tx * TN + j) * (BM + 1) + ty * TM + i] = acc[i][j];
      __syncthreads();
      const int hw_first = m0 - b_first * HW;
      for (int nl = warp; nl < BN; nl += 8) {
        const int col = n0 + nl;
        if (col >= N) break;
        const float bias = __ldg(p.b2 + col);
        int b = b_first, hw = hw_first + lane;
        while (hw >= HW) { hw -= HW; b++; }
#pragma unroll
        for (int jj = 0; jj < BM / 32; jj++) {
          const int ml = lane + 32 * jj, row = m0 + ml;
          if (row < M) {
            const size_t idx = ((size_t)b * N + col) * HW + hw;
            p.out[idx] = Cs[nl * (BM + 1) + ml] + bias + __ldg(p.x + idx);
          }
          hw += 32;
          while (hw >= HW) { hw -= HW; b++; }
        }
      }
      __syncthreads();
    }
  }
}

__global__ void __launch_bounds__(NT, 2) convnext_fused(Params p) {
  extern __shared__ float4 smem4[];
  float* smem = reinterpret_cast<float*>(smem4);
  float* sq_s = smem + GEMM_SMEM_FLOATS;
  float* inv_s = sq_s + MAXIMG * 128;
  float* red_s = inv_s + 8;
  for (int i = threadIdx.x; i < MAXIMG * 128; i += NT) sq_s[i] = 0.f;
  __syncthreads();
  cg::grid_group grid = cg::this_grid();

  phase1(p, smem);
  grid.sync();
  switch (p.cfg2) {
    case 0: gemm_phase<128, 128, 8, 8, 2>(p, smem, sq_s, inv_s, red_s); break;
    case 1: gemm_phase<64, 64, 4, 4, 2>(p, smem, sq_s, inv_s, red_s); break;
    default: gemm_phase<32, 32, 2, 2, 2>(p, smem, sq_s, inv_s, red_s); break;
  }
  grid.sync();
  switch (p.cfg3) {
    case 0: gemm_phase<128, 128, 8, 8, 3>(p, smem, sq_s, inv_s, red_s); break;
    case 1: gemm_phase<64, 64, 4, 4, 3>(p, smem, sq_s, inv_s, red_s); break;
    default: gemm_phase<32, 32, 2, 2, 3>(p, smem, sq_s, inv_s, red_s); break;
  }
}

static int pick_cfg(long M, long N, int grid) {
  const long t128 = ((M + 127) / 128) * ((N + 127) / 128);
  const long t64 = ((M + 63) / 64) * ((N + 63) / 64);
  if (t128 >= 2L * grid) return 0;
  if (t64 >= 2L * grid) return 1;
