          if (img != cur) { if (cur >= 0) { const int il = cur - b_first;
#pragma unroll
              for (int j = 0; j < TN; j++) { if (il < MAXIMG) atomicAdd(&sq_s[il * BN + tx * TN + j], csum[j]); else atomicAdd(p.sumsq + (size_t)cur * N + n0 + tx * TN + j, csum[j]); csum[j] = 0.f; } }
            cur = img; }
          float g[TN];
#pragma unroll
          for (int j = 0; j < TN; j++) { g[j] = gelu_f(acc[i][j] + bia[j]); csum[j] = fmaf(g[j], g[j], csum[j]); }
          float* dst = p.hidden + (size_t)row * N + n0 + tx * TN;
          if (TN == 8) { *reinterpret_cast<float4*>(dst) = make_float4(g[0], g[1], g[2], g[3]); *reinterpret_cast<float4*>(dst + 4) = make_float4(g[4], g[5], g[6], g[7]); }
          else if (TN == 4) { *reinterpret_cast<float4*>(dst) = make_float4(g[0], g[1], g[2], g[3]); }
          else { *reinterpret_cast<float2*>(dst) = make_float2(g[0], g[1]); } } }
      if (cur >= 0) { const int il = cur - b_first;
#pragma unroll
        for (int j = 0; j < TN; j++) { if (il < MAXIMG) atomicAdd(&sq_s[il * BN + tx * TN + j], csum[j]); else atomicAdd(p.sumsq + (size_t)cur * N + n0 + tx * TN + j, csum[j]); } }
      __syncthreads();
      for (int idx = tid; idx < nimg * BN; idx += NT) { const int img = idx / BN, n = idx - img * BN; const float v = sq_s[idx]; sq_s[idx] = 0.f; atomicAdd(p.sumsq + (size_t)(b_first + img) * N + n0 + n, v); }
    } else {
      float* Cs = smem;
#pragma unroll
      for (int i = 0; i < TM; i++)
#pragma unroll
        for (int j = 0; j < TN; j++) Cs[(tx * TN + j) * (BM + 1) + ty * TM + i] = acc[i][j];
      __syncthreads();
      const int hw_first = m0 - b_first * HW;
      for (int nl = warp; nl < BN; nl += 8) { const int col = n0 + nl; if (col >= N) break; const float bias = __ldg(p.b2 + col);
        int b = b_first, hw = hw_first + lane; while (hw >= HW) { hw -= HW; b++; }
#pragma unroll
        for (int jj = 0; jj < BM / 32; jj++) { const int ml = lane + 32 * jj, row = m0 + ml;
          if (row < M) { const size_t idx = ((size_t)b * N + col) * HW + hw; p.out[idx] = Cs[nl * (BM + 1) + ml] + bias + __ldg(p.x + idx); }
          hw += 32; while (hw >= HW) { hw -= HW; b++; } } }
      __syncthreads();
    }
  }
}
extern "C" __global__ void __launch_bounds__(NT, 2) k_p1(const Params* pp) { Params p = *pp; extern __shared__ float4 smem4[]; float* smem = (float*)smem4; phase1(p, smem); }
extern "C" __global__ void __launch_bounds__(NT, 2) k_p2(const Params* pp) { Params p = *pp; extern __shared__ float4 smem4[]; float* smem = (float*)smem4;
  float* sq_s = smem + GEMM_SMEM_FLOATS; float* inv_s = sq_s + MAXIMG * 128; float* red_s = inv_s + 8;
  for (int i = threadIdx.x; i < MAXIMG * 128; i += NT) sq_s[i] = 0.f; __syncthreads();
  switch (p.cfg2) { case 0: gemm_phase<128,128,8,8,2>(p, smem, sq_s, inv_s, red_s); break; case 1: gemm_phase<64,64,4,4,2>(p, smem, sq_s, inv_s, red_s); break; default: gemm_phase<32,32,2,2,2>(p, smem, sq_s, inv_s, red_s); } }
extern "C" __global__ void __launch_bounds__(NT, 2) k_p3(const Params* pp) { Params p = *pp; extern __shared__ float4 smem4[]; float* smem = (float*)smem4;
  float* sq_s = smem + GEMM_SMEM_FLOATS; float* inv_s = sq_s + MAXIMG * 128; float* red_s = inv_s + 8;
  switch (p.cfg3) { case 0: gemm_phase<128,128,8,8,3>(p, smem, sq_s, inv_s, red_s); break; case 1: gemm_phase<64,64,4,4,3>(p, smem, sq_s, inv_s, red_s); break; default: gemm_phase<32,32,2,2,3>(p, smem, sq_s, inv_s, red_s); } }
'''
SMEM = 128*129*4 + 5*128*4 + 64
ks = [cuda_kernel(SRC, n) for n in ("k_p1","k_p2","k_p3")]
for k in ks: k.set_smem(SMEM)
GRID = 296
def pick(M,N):
    t128 = ((M+127)//128)*((N+127)//128); t64 = ((M+63)//64)*((N+63)//64)
    return 0 if t128 >= 2*GRID else (1 if t64 >= 2*GRID else 2)
dev='cuda'
for (B,C,H,W) in [(64,96,112,112),(32,128,64,64),(8,320,32,32),(2,768,7,7),(1,192,28,28),(16,384,14,14)]:
    HW=H*W; M=B*HW; C4=4*C
    r = lambda *s: torch.randn(*s, device=dev)
    x=r(B,C,H,W); dww=r(C,1,7,7)/math.sqrt(7); dwb=r(C); lnw=torch.ones(C,device=dev); lnb=torch.zeros(C,device=dev)
    w1=r(C4,C)/math.sqrt(C); b1=r(C4); gw=r(C4)/math.sqrt(C4); gb=r(C4); w2=r(C,C4)/math.sqrt(C4); b2=r(C)
    out=torch.empty(B,C,H,W,device=dev); xn=torch.empty(M,C,device=dev); stats=torch.empty(M,2,device=dev); hidden=torch.empty(M,C4,device=dev)
    sumsq=torch.zeros(B,C4,device=dev); w1t=torch.empty(C,C4,device=dev); w2t=torch.empty(C4,C,device=dev)
    cfg2=pick(M,C4); cfg3=pick(M,C)
    if W>=32: mode=1; hq=(H+3)//4; wq=(W+31)//32; tiles=B*hq*wq
    else: mode=0; hq=0; wq=0; tiles=(M+127)//128
    ptrs=[t.data_ptr() for t in (x,dww,dwb,lnw,lnb,w1,b1,gw,gb,w2,b2,out,xn,stats,hidden,sumsq,w1t,w2t)]
    buf = struct.pack('<18Q7i2f6i', *ptrs, B,C,H,W,HW,M,C4, 1e-6,1e-6, mode,tiles,hq,wq,cfg2,cfg3)
    pbuf = torch.frombuffer(bytearray(buf+b'\0'*8), dtype=torch.uint8).to(dev)
    def p1(o): ks[0]((GRID,),(256,), pbuf, smem=SMEM)
    def p2(o): ks[1]((GRID,),(256,), pbuf, smem=SMEM)
    def p3(o): ks[2]((GRID,),(256,), pbuf, smem=SMEM)
    def all3(o): p1(o); p2(o); p3(o)
    p1(None); p2(None); torch.cuda.synchronize()
    t1=harness_time(p1,[],[out]); t2=harness_time(p2,[],[out]); t3=harness_time(p3,[],[out]); ta=harness_time(all3,[],[out])
    f2=2*M*C*C4; f3=f2
    print(f"{B},{C},{H},{W}: cfg2={cfg2} cfg3={cfg3} p1_tiles={tiles} mode={mode} | p1 {t1:.1f} us | p2 {t2:.1f} us ({f2/t2/1e6:.1f} TF/s) | p3 {t3:.1f} us ({f3/t3/1e6:.1f} TF/s) | all {ta:.1f}")

